private enum class Phase{LEARN,LAB,BUILD,DEBUG,REVIEW}

@Composable fun PathPilotAppV3(viewModel:PathPilotViewModel){var tab by remember{mutableIntStateOf(0)};var selected by remember{mutableStateOf<Skill?>(null)};BackHandler(enabled=selected!=null){selected=null};Surface(Modifier.fillMaxSize(),color=Color(0xFFF8FBFF)){if(selected!=null)Journey(selected!!){selected=null}else Shell(tab,{tab=it}){selected=it}}}
@Composable private fun Shell(tab:Int,onTab:(Int)->Unit,onSkill:(Skill)->Unit){val labels=listOf("Home","Learn","Mentor","College");val icons=listOf(Icons.Default.Home,Icons.Default.Code,Icons.Default.Psychology,Icons.Default.School);Column(Modifier.fillMaxSize()){Box(Modifier.weight(1f).fillMaxWidth()){when(tab){0->Home(onSkill){onTab(1)};1->Learn(onSkill);2->Mentor();else->College()}};NavigationBar(containerColor=Color.White){labels.forEachIndexed{i,l->NavigationBarItem(tab==i,{onTab(i)},{Icon(icons[i],l)},label={Text(l)})}}}}
@Composable private fun Header(){Row(Modifier.fillMaxWidth().padding(16.dp),verticalAlignment=Alignment.CenterVertically){Box(Modifier.size(43.dp).clip(RoundedCornerShape(13.dp)).background(Blue),contentAlignment=Alignment.Center){Text("➤",color=Color.White,fontSize=24.sp,fontWeight=FontWeight.Black)};Spacer(Modifier.width(10.dp));Column(Modifier.weight(1f)){Row{Text("Path",fontSize=23.sp,fontWeight=FontWeight.Black,color=Navy);Text("Pilot",fontSize=23.sp,fontWeight=FontWeight.Black,color=Blue)};Text("AI Engineering Academy",fontSize=10.sp,color=Gray)};IconButton({}){Icon(Icons.Default.Notifications,"Notifications")};Box(Modifier.size(35.dp).clip(CircleShape).background(BlueSoft),contentAlignment=Alignment.Center){Icon(Icons.Default.Person,"Profile",tint=Blue)}}}
@Composable private fun Home(onSkill:(Skill)->Unit,onLearn:()->Unit){val c=LocalContext.current;val p=remember{c.getSharedPreferences("pathpilot_engine",Context.MODE_PRIVATE)};val done=skills.count{p.getBoolean("done_${it.id}",false)};val next=skills.firstOrNull{!p.getBoolean("done_${it.id}",false)};LazyColumn(Modifier.fillMaxSize(),contentPadding=PaddingValues(bottom=18.dp),verticalArrangement=Arrangement.spacedBy(14.dp)){item{Header()};item{Column(Modifier.padding(horizontal=18.dp)){Text("Hi Gaurav 👋",fontSize=16.sp,fontWeight=FontWeight.Bold,color=Navy);Text("Learn languages. Build websites. Ship real software.",fontSize=12.sp,color=Gray)}};item{Card(Modifier.padding(horizontal=18.dp).fillMaxWidth(),shape=RoundedCornerShape(24.dp),colors=CardDefaults.cardColors(BlueSoft)){Column(Modifier.padding(20.dp)){Text("LEARN. PRACTICE. BUILD. GROW.",fontSize=11.sp,fontWeight=FontWeight.Black,color=Blue);Spacer(Modifier.height(6.dp));Text("Your path to real\nengineering skills.",fontSize=26.sp,lineHeight=31.sp,fontWeight=FontWeight.Black,color=Navy);Spacer(Modifier.height(6.dp));Text("From C and Python to React, backend, AI, cybersecurity and deployment.",fontSize=12.sp,color=Gray);Spacer(Modifier.height(14.dp));Button({next?.let(onSkill)},enabled=next!=null,shape=RoundedCornerShape(14.dp)){Icon(Icons.Default.PlayArrow,null);Spacer(Modifier.width(5.dp));Text("Continue learning")}}}};item{Column(Modifier.padding(horizontal=18.dp)){Row(verticalAlignment=Alignment.CenterVertically){Text("Academy progress",fontSize=18.sp,fontWeight=FontWeight.Black,color=Navy,modifier=Modifier.weight(1f));Text("$done/${skills.size}",fontSize=12.sp,color=Blue,fontWeight=FontWeight.Bold)};Spacer(Modifier.height(8.dp));LinearProgressIndicator({done.toFloat()/skills.size},Modifier.fillMaxWidth().height(7.dp).clip(CircleShape),color=Blue,trackColor=Color(0xFFDDE8F5))}};item{Row(Modifier.padding(horizontal=18.dp),horizontalArrangement=Arrangement.spacedBy(9.dp)){Feature(Icons.Default.Psychology,"AI Teacher",PurpleSoft);Feature(Icons.Default.Code,"Coding Lab",BlueSoft);Feature(Icons.Default.BugReport,"Debug Coach",OrangeSoft)}};item{Mission(next,onSkill)};item{OutlinedButton(onLearn,Modifier.padding(horizontal=18.dp).fillMaxWidth(),shape=RoundedCornerShape(14.dp)){Text("Explore all languages & web development");Spacer(Modifier.width(5.dp));Icon(Icons.Default.ArrowForward,null)}}}}
