@Composable private fun Learn(onSkill:(Skill)->Unit){var q by remember{mutableStateOf("")};var cat by remember{mutableStateOf("All")};val cats=listOf("All","Programming","Web Development","Backend","Professional","AI Development","Cybersecurity","Architecture","Capstone");val list=skills.filter{(cat=="All"||it.category==cat)&&(q.isBlank()||it.title.contains(q,true)||it.concept.contains(q,true))};LazyColumn(Modifier.fillMaxSize(),contentPadding=PaddingValues(bottom=18.dp),verticalArrangement=Arrangement.spacedBy(10.dp)){item{Header()};item{Column(Modifier.padding(horizontal=18.dp)){Text("Learn",fontSize=27.sp,fontWeight=FontWeight.Black,color=Navy);Text("Every major language and the full web-development path.",fontSize=12.sp,color=Gray);Spacer(Modifier.height(10.dp));OutlinedTextField(q,{q=it},Modifier.fillMaxWidth(),singleLine=true,leadingIcon={Icon(Icons.Default.Search,null)},placeholder={Text("Search Python, Java, React, CSS…")},shape=RoundedCornerShape(14.dp))}};item{Row(Modifier.horizontalScroll(rememberScrollState()).padding(horizontal=18.dp),horizontalArrangement=Arrangement.spacedBy(7.dp)){cats.forEach{Surface(Modifier.clickable{cat=it},shape=RoundedCornerShape(20.dp),color=if(cat==it)Blue else Color.White){Text(it,Modifier.padding(horizontal=13.dp,vertical=8.dp),fontSize=10.sp,color=if(cat==it)Color.White else Gray)}}}};items(list){SkillItem(it,onSkill)}}}
@Composable private fun SkillItem(s:Skill,onSkill:(Skill)->Unit){val icon=when(s.category){"Cybersecurity"->Icons.Default.Security;"Web Development"->Icons.Default.Language;"Professional"->Icons.Default.Build;"Backend"->Icons.Default.Storage;"AI Development"->Icons.Default.Psychology;"Programming"->Icons.Default.Code;else->Icons.Default.School};Card(Modifier.padding(horizontal=18.dp).fillMaxWidth().clickable{onSkill(s)},shape=RoundedCornerShape(17.dp),colors=CardDefaults.cardColors(Color.White)){Row(Modifier.padding(15.dp),verticalAlignment=Alignment.CenterVertically){Box(Modifier.size(45.dp).clip(RoundedCornerShape(13.dp)).background(BlueSoft),contentAlignment=Alignment.Center){Icon(icon,null,tint=Blue)};Spacer(Modifier.width(12.dp));Column(Modifier.weight(1f)){Text("${s.category} • ${s.level}",fontSize=9.sp,fontWeight=FontWeight.Black,color=Blue);Text(s.title,fontSize=15.sp,fontWeight=FontWeight.Bold,color=Navy);Text(s.concept,fontSize=11.sp,color=Gray)};Icon(Icons.Default.ArrowForward,null,tint=Color(0xFF94A3B8))}}}
@Composable private fun Journey(skill:Skill,onBack:()->Unit){val c=LocalContext.current;val scope=rememberCoroutineScope();val prefs=remember{c.getSharedPreferences("pathpilot_engine",Context.MODE_PRIVATE)};var phase by remember{mutableStateOf(Phase.LEARN)};var work by remember{mutableStateOf("")};var feedback by remember{mutableStateOf("")};var busy by remember{mutableStateOf(false)};val phases=Phase.values();val text=when(phase){Phase.LEARN->skill.concept;Phase.LAB->skill.mission;Phase.BUILD->skill.build;Phase.DEBUG->skill.debug;Phase.REVIEW->skill.review};Column(Modifier.fillMaxSize()){Row(Modifier.fillMaxWidth().padding(10.dp),verticalAlignment=Alignment.CenterVertically){IconButton(onBack){Icon(Icons.Default.ArrowBack,"Back")};Column(Modifier.weight(1f)){Text(skill.title,fontSize=20.sp,fontWeight=FontWeight.Black,color=Navy);Text(skill.category+" • "+skill.level,fontSize=10.sp,color=Blue)}};ScrollableTabRow(selectedTabIndex=phase.ordinal,edgePadding=12.dp){phases.forEach{Tab(selected=phase==it,onClick={phase=it},text={Text(it.name)})}};LazyColumn(Modifier.weight(1f),contentPadding=PaddingValues(18.dp),verticalArrangement=Arrangement.spacedBy(12.dp)){item{Card(Modifier.fillMaxWidth(),shape=RoundedCornerShape(20.dp),colors=CardDefaults.cardColors(BlueSoft)){Column(Modifier.padding(18.dp)){Text(phase.name,fontSize=10.sp,fontWeight=FontWeight.Black,color=Blue);Text(text,fontSize=17.sp,fontWeight=FontWeight.Bold,color=Navy);Spacer(Modifier.height(8.dp));Text("Don't just read it. Explain your reasoning, then try the task.",fontSize=12.sp,color=Gray)}}};if(phase!=Phase.LEARN){item{OutlinedTextField(work,{work=it},Modifier.fillMaxWidth().heightIn(min=150.dp),label={Text(if(phase==Phase.DEBUG)"Bug, code or debugging evidence" else "Your solution / notes")},shape=RoundedCornerShape(16.dp))};item{Button(enabled=!busy,onClick={busy=true;scope.launch{feedback=GeminiMentorService.askGeminiMentor(c,"Act as a ${phase.name} coach for ${skill.title}. Give feedback on this learner work: $work. Teach the missing concept, point out mistakes, and give one next exercise.","Skill=${skill.title}; level=${skill.level}; phase=${phase.name}");busy=false}},Modifier.fillMaxWidth(),shape=RoundedCornerShape(14.dp)){Text(if(busy)"AI is reviewing…" else "Get AI feedback")}}};if(feedback.isNotBlank()){item{Card(Modifier.fillMaxWidth(),shape=RoundedCornerShape(18.dp),colors=CardDefaults.cardColors(Color.White)){Column(Modifier.padding(16.dp)){Text("AI mentor",fontWeight=FontWeight.Black,color=Blue);Spacer(Modifier.height(6.dp));Text(feedback,fontSize=13.sp,color=Navy)}}}};item{Button(onClick={if(phase.ordinal<phases.lastIndex)phase=phases[phase.ordinal+1]else{prefs.edit().putBoolean("done_${skill.id}",true).apply();onBack()}},Modifier.fillMaxWidth(),shape=RoundedCornerShape(14.dp)){Text(if(phase==Phase.REVIEW)"Complete skill" else "Next phase");Spacer(Modifier.width(5.dp));Icon(Icons.Default.ArrowForward,null)}}}}
@Composable private fun Mentor(){val c=LocalContext.current;val scope=rememberCoroutineScope();var q by remember{mutableStateOf("")};var answer by remember{mutableStateOf("")};var busy by remember{mutableStateOf(false)};LazyColumn(Modifier.fillMaxSize(),contentPadding=PaddingValues(bottom=20.dp),verticalArrangement=Arrangement.spacedBy(12.dp)){item{Header()};item{Column(Modifier.padding(horizontal=18.dp)){Text("AI Mentor",fontSize=28.sp,fontWeight=FontWeight.Black,color=Navy);Text("Ask about any language, web stack, backend, debugging or college topic.",fontSize=12.sp,color=Gray)}};item{OutlinedTextField(q,{q=it},Modifier.padding(horizontal=18.dp).fillMaxWidth().heightIn(min=120.dp),label={Text("What are you stuck on?")},shape=RoundedCornerShape(16.dp))};item{Button(enabled=q.isNotBlank()&&!busy,onClick={busy=true;scope.launch{answer=GeminiMentorService.askGeminiMentor(c,q,"Learner is following Path-Pilot's multi-language engineering and web-development curriculum.");busy=false}},Modifier.padding(horizontal=18.dp).fillMaxWidth(),shape=RoundedCornerShape(14.dp)){Text(if(busy)"Thinking…" else "Ask Gemini 3.8")}};if(answer.isNotBlank())item{Card(Modifier.padding(horizontal=18.dp).fillMaxWidth(),shape=RoundedCornerShape(18.dp),colors=CardDefaults.cardColors(Color.White)){Column(Modifier.padding(16.dp)){Text("Mentor response",fontWeight=FontWeight.Black,color=Blue);Spacer(Modifier.height(7.dp));Text(answer,fontSize=13.sp,color=Navy)}}};item{Text("Suggested",Modifier.padding(horizontal=18.dp),fontWeight=FontWeight.Black,color=Navy)};items(listOf("Which language should I learn first and why?","Teach me HTML + CSS by building a website","How do React frontend and FastAPI backend connect?","Explain Git, GitHub, PR and CI like a real developer","Give me a safe web-security lab exercise")){Text(it,Modifier.padding(horizontal=18.dp).fillMaxWidth().clickable{q=it}.background(Color.White,RoundedCornerShape(14.dp)).padding(14.dp),color=Navy,fontSize=12.sp)}}}
